import { Card, Input, Space, Tabs, Tag } from "@arco-design/web-react";
import React, { useEffect, useMemo, useState } from 'react';
import LibraryList from '../LibraryList';
import AllList from '../AllList';
import LibraryModules from '../LibraryModules';
import styles from '../style.module.less';
import Store from '../store';
import { observer } from "mobx-react-lite";
import { ModuleListProps } from "../interface";



function Index(props: ModuleListProps){
    const [store] = useState(() => new Store());
    store.props = props;

    const extraRender = useMemo(() => {
        switch(store.activeTab){
            case "1":
                // return (
                //     <Input.Search
                //         placeholder="请输入"
                //         onPressEnter={() => {

                //         }}
                //     />
                // )
            break;    
            case "2":
                return (
                    <Input.Search
                        placeholder="请输入"
                        value={store.input}
                        onChange={store.setInput}
                        onPressEnter={() => {
                            store.name = store.input;
                            store.initModules()
                        }}
                    />
                )
            break;
        }
        return null;
    },[store.activeTab, store.input])

    useEffect(() => {
        store.initModules();
    },[store.labelKeys])


    return <AllList store={store}/>;
    
    return (
        <Tabs
            activeTab={store.activeTab}
            className={styles.tabs}
            onChange={store.setActiveTab}
            extra={extraRender}
        >
            <Tabs.TabPane key="1" title="组件库">
                <LibraryList store={store}/>
            </Tabs.TabPane>
            <Tabs.TabPane key="2" title="其他组件素材">
                <AllList store={store}/>
            </Tabs.TabPane>
            {store.tabs.map((o) => {
                return (
                    <Tabs.TabPane key={o.id} title={o.name}>
                        <LibraryModules store={store} uid={o.id} />
                    </Tabs.TabPane>
                )
            })}
        </Tabs>
    )
}

export default observer(Index);