import { isBuilder, isJsxString } from "@/utils/is";
import { Button, Switch, SwitchProps } from "@arco-design/web-react";
import { IconCodeSquare } from "@arco-design/web-react/icon";
import React, { useMemo, useState } from "react";
import EditFunction from "../EditFunction";
import { jsStringToJs, jsTojsString } from "@/utils/js";

interface EditSwitchProps extends SwitchProps {
}

const EditSwitch = (props: any) => {

    // 判断如果是Jsx 则转为函数编辑
    const isJsx = useMemo(() => {
        return isJsxString(props.value)
    },[props.value])


    console.log('props', props, isJsx)

    return (
        <div className="flex items-center">
            {isJsx? (
                <EditFunction
                    value={jsStringToJs(props.value)}
                    onChange={(val) => props.onChange && props.onChange(jsTojsString(val))}
                />
            ) : (
                <Switch
                    checked={props.value}
                    {...props}
                />
            )}
        </div>
    )
}

export default EditSwitch;