import React, { useEffect, useMemo, useState } from 'react';
import {
  Table,
  TableProps,
  TableColumnProps,
  Checkbox,
  InputNumber,
  Button,
  Input,
  Space,
  Select,
} from '@arco-design/web-react';
import {
  IconArrowDown,
  IconArrowUp,
  IconDelete,
  IconPlus,
} from '@arco-design/web-react/icon';
import Store from './store';
import './style.less';
import { alphabeticKeys } from '@/utils/schema';
import { AnyInput } from '@/components/custom';
import { EditorColor } from '@/components/custom';
export interface EditorColumnsProps extends TableColumnProps {
  // 参数类型
  valueType?: 'input' | 'checkout' | 'number' | 'text' | 'any' | "index" | "letter" | "color";
  dataIndex: string;
}
export interface EditorTableProps extends TableProps<any> {
  columns: EditorColumnsProps[];
  value?: any;
  onChange?: any;
  // 是否显示操作栏
  notOperation?: boolean;
  // 是否允许添加
  notAdd?: boolean;
}
const EditorTable = ({ notOperation, notAdd, ...props }: EditorTableProps) => {
  const [rowKey] = useState(() => typeof props.rowKey === "string"? props.rowKey : 'id');
  const [store] = useState(() => new Store());
  const data = props.value || [];


  useEffect(() => {
    // 监听外部值的修改，并且判断rowKey 参数是否存在，不存在自动补全
    if (Array.isArray(props.value) && !Object.is(store.value, props.value)) {
      store.setValue(props.value.map((o) => ({
        [rowKey]: Math.random().toString(32).slice(2),
        ...o,
      })));
    }else {
      store.setValue([])
    }
  }, [props.value]);

  const onChange = (list) => {
    console.log('props', props)
    // 是否存在序列
    const column = props.columns.find((o) => o.valueType === 'index' || o.valueType === 'letter');
    const result = list.map((o, index) => {
      if(column){
        return {
          ...o,
          [column.dataIndex]: column.valueType === 'index'? index : alphabeticKeys[index],
        }
      }
      return {
        ...o,
      }
    })
    if(!props.value){
      // 在value 接管状态时，直通过props.value 更新 store，消除误差
      store.setValue(result);
    }
    if (props.onChange) props.onChange(result);
  };

  const onChangeItem = (i: number, item: any) => {
    const result = [...store.value];
    result[i] = item;
    onChange(result);
  };


  const columns: TableColumnProps[] = useMemo(() => {
    if (!props.columns) return [];
    const result = [
      ...props.columns.map((o: EditorColumnsProps, i: number) => {
        if (!o.render && o.valueType !== 'text') {
          o.render = (value: any, record, index: number) => {
            switch (o.valueType) {
              case 'index':
                // return index;
              case 'letter':
                // return alphabeticKeys[index];
                return value;
              case 'any':
                return (
                  <AnyInput
                    key={record[rowKey]}
                    value={value}
                    onChange={(val) => 
                      onChangeItem(index, { ...record, [o.dataIndex]: val })
                    }
                  />
                )
              case 'checkout':
                return (
                  <Checkbox
                    checked={value}
                    key={record[rowKey]}
                    onChange={(val) =>
                      onChangeItem(index, { ...record, [o.dataIndex]: val })
                    }
                  ></Checkbox>
                );
              case 'number':
                return (
                  <InputNumber
                    placeholder="请输入"
                    key={record[rowKey]}
                    value={value}
                    onChange={(val) =>
                      onChangeItem(index, { ...record, [o.dataIndex]: val })
                    }
                  />
                );
              case 'color':
                return (
                  <EditorColor 
                    key={record[rowKey]}
                    value={value}
                    onChange={(val) => {
                      onChangeItem(index, { ...record, [o.dataIndex]: val })
                    }}
                  />
                )
              default:
                return (
                  <Input
                    placeholder="请输入"
                    key={record[rowKey]}
                    value={value}
                    onChange={(val) =>
                      onChangeItem(index, { ...record, [o.dataIndex]: val })
                    }
                  />
                );
            }
          };
        }
        return o;
      }),
    ];
    // 是否允许展示操作按钮
    if(!notOperation){
      result.push(      {
        title: '操作',
        dataIndex: rowKey,
        width: 60,
        render: (_, item, index) => (
          <Space size="mini">
            <Button
              size="mini"
              shape="circle"
              status="danger"
              type="primary"
              icon={<IconDelete />}
              onClick={() => {
                onChange(
                  store.value.filter((o: any) => o[rowKey] !== item[rowKey])
                );
              }}
            />
            {Boolean(index) ? (
                <Button
                  size="mini"
                  shape="circle"
                  type="primary"
                  icon={<IconArrowUp />}
                  onClick={() => {
                    store.value.splice(index, 1);
                    store.value.splice(index - 1, 0, item);
                    onChange([...store.value]);
                  }}
                />
            ) : (
              <Button
                size="mini"
                shape="circle"
                type="primary"
                icon={<IconArrowDown />}
                onClick={() => {
                  store.value.splice(index, 1);
                  store.value.splice(index + 1, 0, item);
                  onChange([...store.value]);
                }}
              />
            )}
          </Space>
        ),
      })
    }
    return result;
  }, [props.columns]);

  return (
    <>
      <Table
        className="editor-table"
        pagination={false}
        rowKey={rowKey}
        {...props}
        data={data}
        onChange={undefined}
        columns={columns}
      />
      {!notAdd && (
        <Button 
          type='outline'
          style={{ width: '100%', marginTop: 8 }}
          icon={<IconPlus />}
          onClick={() =>
            onChangeItem(store.value.length, {
              [rowKey]: Math.random().toString(32).slice(2),
            })
          }
        >添加</Button>
      )}
    </>
  );
};

export default EditorTable;
