import React, { useMemo, useState } from 'react';
import styles from './index.module.less';
import { Button, Tooltip, Message } from '@arco-design/web-react';
import { IconEye, IconPalette, IconSettings } from '@arco-design/web-react/icon';
import PageCss from './component/PageCss';
import Setting from './component/Setting';
import Preview from '../../Preview';
import Store from '../../store';
import ajax from '@/utils/ajax';
import { moduleStore } from "react-converter-code";
import { ButtonItem, controlType } from '../../interface';
import AsyncButton from '@/components/custom/AsyncButton';

interface ControlProps {
    store: Store;
    controlList?: ButtonItem[];
}
const Control = ({ store, controlList = [] }: ControlProps) => {

    const [key, setKey] = useState<controlType>();
    const buttons = useMemo(() => {
        const list: ButtonItem[] = [
            ...controlList,
            {
                key: "view",
                icon: <IconEye />,
                tooltip: "页面预览",
            },
            {
                key: "css",
                icon: <IconPalette />,
                tooltip: "Less 文件样式"
            },
        ]
        if(store.isComponent){
            list.push(   {
                key: "setting",
                icon: <IconSettings />,
                tooltip: "模块设置",
            })
        }
        return list;
    },[])

    const content = useMemo(() => {
        switch(key){
            case "css":
                return ( 
                    <PageCss
                        lessStr={store.lessStr}
                        onCancel={() => setKey(undefined)}
                        onSuccess={(less) => {
                            setKey(undefined)
                            store.setLess(less);
                        }}
                    />
                )
            case "view":
                return (
                    <Preview
                        pageStore={store}
                        visible
                        onCancel={() => {
                            setKey(undefined)
                        }} 
                    />
                )
            case "setting":
                return (
                    <Setting
                        id={store.uid}
                        onCancel={() => setKey(undefined)}
                        onSuccess={(res) => {
                            const element = moduleStore.elements.get(store.uid);
                            return ajax.post('/apijson/put', {
                                "Module": {
                                    id: element.uid,
                                    ...res,
                                    extraInfo: {
                                        ...element.extraInfo,
                                        ...res.extraInfo,
                                    }
                                }
                            }).then(() => {
                                setKey(undefined)
                                moduleStore.updateElement(store.uid, {
                                    ...element,
                                    ...res,
                                    extraInfo: {
                                        ...element.extraInfo,
                                        ...res.extraInfo,
                                    }
                                })
                                Message.success("保存成功");
                            })
                        }}
                    />
                )
        }
    },[key])
    

    return (
        <div className={styles['custom-page-control']}>
            {buttons.map((o, i) => {
                const isPrimary = o.key === key;
                return (
                    <Tooltip key={o.key} content={o.tooltip}>
                        <AsyncButton
                            type={isPrimary? 'primary' : undefined}
                            icon={o.icon}
                            onClick={(e) => {
                                e.stopPropagation();
                                if(o.onClick){
                                    return o.onClick(e);
                                }else {
                                    setKey(isPrimary? undefined : o.key)
                                }
                            }}
                        />
                    </Tooltip>
                )
            })}
            {content}
        </div>
    )
}

export default Control;