import {
    Button,
    Card,
    CardProps,
    Form,
    Space,
    Tooltip,
    Link,
    Message,
    Collapse,
    Input,
    Tabs,
    Drawer,
} from '@arco-design/web-react';
import { useObserver } from 'mobx-react-lite';;
import PageStore from '../store';
import store from './store';
import { toJS } from 'mobx';
import styles from './index.module.less';
import { useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { IconAt, IconCodeSquare, IconCopy, IconDelete, IconSubscribe } from '@arco-design/web-react/icon';
import Store from './store';
import { set, get } from 'lodash';
import { MonacoJSONEditor } from '@/components/MonacoEditor';
import { ExpressionBuilderContenxt, ExpressionSelect, MyErrorBoundary } from '@/components/custom';
import { CustomPageContext } from '../context';
import Variable from '../components/Variable';
import React from 'react';
import { isBuilder, isBuilderFun } from '@/utils/is';
import { delayedFunction } from '@/utils';
import { FormGenerate, FormGenerateContext } from "react-converter-code";
import { getFormats } from '@/environments/formats';
import { FormBusinessContext } from '@/components/contexts/FormBusinessContext';
import TableExtra from '../components/TableExtra';
import { ModuleItem } from '../interface';

const IconView = ({ value, onChange, onChangeValue }: any) => {
    return (
        <ExpressionSelect
            onChange={({ value }) => {
                if(onChange) onChange(value);
            }}
        >
            <Link icon={<IconAt />} >
                {isBuilder(value)? isBuilderFun(value)? '' : value : ''}
            </Link>
        </ExpressionSelect>
    )
}

export interface SettingProps extends CardProps {
    // 是否显示预览按钮
    isPreview?: boolean;
    // 预览按钮点击事件
    onPriview?: () => boolean;
}

interface Setting extends SettingProps {
    pageStore: PageStore;
    onModuleCode?: (module: ModuleItem) => void;
    store: Store;
}

export default ({ 
    pageStore,
    store, 
    onPriview,
    onModuleCode,
    isPreview = true,
    ...props 
}: Setting) => {

    const [form] = Form.useForm();
    useState(() => {
        store.form = form;
        if(pageStore.parse){
            pageStore.parse.form = form;
        }
    })

    return useObserver(() => {

        /**
         * 设置参数修改主要包含 页面设置 page
         * 和组件设置 props 
         * 在这边根据selectId 当前选中值，来确认正在更新谁的数据
         */
        const [
            title,
            initialValues,
            onValuesChange,
        ] = useMemo(() => {
             form.clearFields();
            const { selectId, page, setPage, mapStore } = pageStore;
            const eStore = mapStore.get(selectId); // code 更新后uid 可能会变更
            if(selectId && pageStore.selectItem && eStore){
                // form.setFieldsValue(toJS(eStore.props));
                // console.log('pageStore.selectItem', pageStore.selectItem)
                const { nickName, name, source } = pageStore.selectItem;
                const isCustom = source == "custom";
                return [
                    (
                        <div className={styles.cardTitle}>
                            {/* <span className={styles.cardTitleNmae}>{pageStore.selectItem.name}：{pageStore.selectId}</span> */}
                            <span className={styles.cardTitleNmae}>{nickName || name}</span>
                            <Space>
                                <Button
                                    size="mini" 
                                    status='danger' 
                                    type='primary' 
                                    shape='circle' 
                                    icon={<IconDelete />} 
                                    onClick={() => {
                                        pageStore.deleteList(selectId)
                                    }}
                                />
                                <Button
                                    size="mini" 
                                    type='primary' 
                                    shape='circle'
                                    icon={<IconCopy />}
                                    onClick={() => {
                                        pageStore.copyList(selectId);
                                    }}
                                />
                                {(isCustom && onModuleCode) && (
                                    <Tooltip content="模块开发">
                                        <Button
                                            size="mini"
                                            type="primary"
                                            onClick={() => {
                                                onModuleCode(pageStore.selectItem)
                                            }}
                                            icon={<IconCodeSquare />}
                                        />
                                    </Tooltip>
                                )}
                            </Space>
                        </div>
                    ),
                    toJS(eStore.props),
                    eStore.setProps,
                ]
            }else {
                // form.setFieldsValue(toJS(page));
                return [
                    <div className={styles.cardTitle}>
                        <span>{store.title}</span>
                        {isPreview && (
                            <Button 
                                size="small"
                                type='primary'
                                shape='round'
                                onClick={() => {
                                    store.setJsonVisible(true);
                                    console.log('pageStore', pageStore.page)
                                    // 这里可以确保 props 不会存储 function 类型
                                    store.setData(JSON.parse(JSON.stringify(toJS(pageStore.page))));
                                }}
                            >
                                JSON
                            </Button>
                        )}
                    </div>,
                    toJS(page),
                    setPage,
                ]
            }
        },[pageStore.selectId])

        useEffect(() => {
            // form.clearFields();
            // 用户选中组件时，切换组件编辑内容
            if(pageStore.selectId){
                // 如果找不到，则可能和父节点被一起删除 (目前暂无此逻辑，先写下做个兼容)
                if(pageStore.selectItem){
                    if(pageStore.selectItem.source === "context"){
                        store.setSchema({ type: "object", properties: { value: { format: "nodeInput" }} });
                    }else {
                        store.setSchema(pageStore.selectItem.props);
                    }
                }else {
                    pageStore.setSelectId('')
                }
            }else {
                store.init();
            }
            // form.setFieldsValue(initialValues);
        },[pageStore.selectId])
        

        const getLabelField = useCallback((o) => {
            return  (
                <span
                    style={{
                        whiteSpace: "nowrap",
                        overflow: 'hidden'
                    }}
                    onClick={(e) => {
                        // 默认点击label 会修改switch 事件，阻止事务传输
                        e.stopPropagation()
                        e.preventDefault();
                    }}
                >
                    <Tooltip content="删除当前属性，在props中不会传值">
                        <IconDelete
                            style={{ cursor: 'pointer', color: "red" }}
                            onClick={(e) => {
                                console.log('o.field', o);
                                if(o.field){
                                    const data = form.getFieldsValue();
                                    form.clearFields(o.field);
                                    delete data[o.field];
                                    // console.log('setFieldValue', o.field, initialValues, form.getFields(), form.getFieldsValue())
                                    onValuesChange(data)
                                    Message.success(`【${o.label}】属性已删除`)
                                }else {
                                    Message.warning("数据未找到")
                                }
                            }}
                        />
                    </Tooltip>
                    {o.label}
                    <Form.Item noStyle field={o.field} >
                        <IconView
                            // onChangeValue={({ value }) => {
                            //     console.log('setFieldValue', o, value)
                            //     form.setFieldValue(o.field, value);
                            //     onValuesChange(form.getFieldsValue())
                            // }}
                        />
                    </Form.Item>
                </span>
            )
        },[onValuesChange])

        const forms = useMemo(() => {
            const types =  {
                styles: [],
                events: [],
                props: [],
                defaultKey: "events",
            }
            for (const item of store.filterFormList) {
                if("show" in item && item.show === false){
                    continue;
                }
                if(item.valueType === "function"){
                    types.events.push(item);
                }else if(["class", "style"].includes(item.valueType)){
                    types.styles.push(item);
                }else if(item.valueType === "json" && item?.fieldProps.type == "css"){
                    types.styles.push(item);
                }else if(item.field === "className"){
                    types.styles.push(item);
                }else {
                    types.props.push(item);
                }
            }
            // console.log('forms', types);
            if(types.props.length){
                types.defaultKey = "props";
            }else if(types.styles.length){
                types.defaultKey = "types";
            }
            return types;
            // return store.formList;
        },[store.filterFormList])

        const parentContext = useContext(CustomPageContext);

        const contextValue = useMemo(() => {
            if(parentContext) return parentContext;
            // 编辑页面中会打开其他页面，这里可对参数进行编辑
            return {
                pageStore: pageStore,
                platform: pageStore.platform,
                pageSchema: {},
            }
        },[])


        const ExpressProvider: any = useMemo(() => {
            if(pageStore.nodeContent || pageStore.isFunction){
                // node 和 function 节点类型，参数从props 获取
                // console.log('nodeContent', pageStore.nodeContent)
                return (props) => props.children;
            }
            return ExpressionBuilderContenxt.Provider
        },[])

        const formItemList = useMemo(() => {
            const result: any[] = [                   
                {
                    label: "key",
                    field: "key",
                    valueType: "nodeInput",
                },
                {
                    label: "id",
                    field: "id",
                    valueType: "nodeInput",
                },
                {
                    label: "ref",
                    field: "ref",
                    valueType: "nodeInput",
                    formItemProps: {
                        extra: "绑定变量需要通过React.createRef创建" 
                    }
                }
            ]
            return result;
        },[pageStore.selectItem])


        // if(!formList.length) return null;

        const widgets = useMemo(() => {
            return {
                Variable,
                ...pageStore.widgets
            }
        },[])


        const generateContent = useMemo(() => {
            return {
                formats: getFormats()
            }
        },[])

        return (
            <FormGenerateContext.Provider value={generateContent}>
            <CustomPageContext.Provider value={contextValue}>
            <ExpressProvider value={pageStore.pageData.bind(pageStore)}>
            <FormBusinessContext.Provider value={pageStore.businessBody}>
            <div className={styles.component}>
                <Card
                    size="small"
                    title={title}
                    className={styles.card}
                    {...props}
                >
                    <Form
                        key={pageStore.selectId}
                        form={form}
                        className={styles.form}
                        style={{ boxSizing: 'border-box' }}
                        layout="vertical"
                        initialValues={initialValues}
                        onChange={(val, vals: any) => {
                            // console.log('onValuesChange', val, vals);
                            onValuesChange(vals)
                        }}
                    >
                        {/* <Selector 
                            schema={store.schema}
                            mode="multiple"
                        /> */}
                        <MyErrorBoundary>
                        {pageStore.selectItem && (
                            <div className={styles.center}>
                                <Button type="primary"
                                    onClick={() => {
                                        const eStore = pageStore.mapStore.get(pageStore.selectId);
                                        store.setJsonVisible(true);
                                        // 这里可以确保 props 不会存储 function 类型
                                        store.setData(JSON.parse(JSON.stringify(eStore.props)));
                                    }}
                                >
                                    JSON
                                </Button>
                                <Input.Search
                                    value={store.search}
                                    onChange={store.setSearch}
                                    allowClear
                                    placeholder="搜索参数"
                                />
                                {(store.module.source === "custom" && pageStore.openModuleEidt) && (
                                    <Button
                                        type="primary"
                                        onClick={() => {
                                            pageStore.openModuleEidt(pageStore.selectItem.key)
                                        }}
                                    >编辑</Button>
                                )}
                            </div>
                        )}
                        <Tabs 
                            className={styles.tabs}
                            key={forms.defaultKey}
                            defaultActiveTab={forms.defaultKey}
                        >
                            {pageStore.selectItem && pageStore.selectItem.source != "basics" && (
                                // 基础组件不存在控制器功能
                                <Tabs.TabPane key="control" title={(<IconSubscribe />)}>
                                    <FormGenerate
                                        form={form}
                                        cols={24}
                                        formItemProps={{ layout: "horizontal" }}
                                        formItemList={formItemList}
                                    />
                                </Tabs.TabPane>
                            )}
                            {Boolean(forms.styles.length) && (
                                <Tabs.TabPane key="styles" title="样式">
                                    <FormGenerate 
                                        form={form}
                                        cols={24}
                                        formItemList={forms.styles}
                                        getLabelField={getLabelField}
                                        widgets={widgets}
                                    />
                                </Tabs.TabPane>
                            )}
                            {Boolean(forms.props.length) && (
                                <Tabs.TabPane key="props" title="属性">
                                    <FormGenerate 
                                        form={form}
                                        cols={24}
                                        formItemList={forms.props}
                                        getLabelField={getLabelField}
                                        widgets={widgets}
                                    />
                                </Tabs.TabPane>
                            )}
                            {Boolean(forms.events.length) && (
                                <Tabs.TabPane key="events" title="事件">
                                    <FormGenerate 
                                        form={form}
                                        cols={24}
                                        formItemList={forms.events}
                                        getLabelField={getLabelField}
                                        widgets={widgets}
                                    />
                                </Tabs.TabPane>
                            )}
                        </Tabs>
                        </MyErrorBoundary>
                    </Form>
                </Card>
                {store.jsonVisible && (
                    <Drawer
                        width={600}
                        title={pageStore.selectItem? pageStore.selectItem.name : "Component"}
                        visible={store.jsonVisible}
                        placement="right"
                        onOk={() => {
                            if(pageStore.selectId){
                                const eStore = pageStore.mapStore.get(pageStore.selectId);
                                form.setFieldsValue(store.data);
                                eStore.setProps(store.data);
                            }else {
                                form.setFieldsValue(store.data);
                                pageStore.setPage(store.data);
                            }
                            store.setJsonVisible(false);
                        }}
                        onCancel={() => {
                            store.setJsonVisible(false);
                        }}
                    >
                        <MonacoJSONEditor value={store.data} onChange={store.setData} selectionVariable />
                    </Drawer>
                )}
            </div>
            </FormBusinessContext.Provider>
            </ExpressProvider>
            </CustomPageContext.Provider>
            </FormGenerateContext.Provider>
        );
    });
};
  