import React, { useEffect, useMemo } from "react";
import { Divider, Form, Input, Select, Radio, Checkbox, Button, Card } from "@arco-design/web-react";
import { functionConfig, functionTypeOptions, functionTypes } from "@/types/function";
import EditFunction from "../EditFunction";
import styles from "./index.module.less";
import FormBody from './FornBody';
import JSONList from "../JSONList";
import { IconArrowFall, IconArrowRise, IconDelete } from "@arco-design/web-react/icon";

interface EditFunctionConfigProps {
    // 是否为子事件
    isChild?: boolean;
    // 纯函数，不允许配置
    pureFunction?: boolean;
    value?: functionConfig | string;
    onChange?: (value: functionConfig | string) => void;
}
export default (props: EditFunctionConfigProps) => {
    const { value, pureFunction } = props;

    const [form] = Form.useForm();
    const size = "small";
    const valueType = typeof value;

    useEffect(() => {
        if(value){
            if(valueType === "string"){
                form.setFieldValue('type', 'js');
            }else if(valueType === "object") {
                form.setFieldsValue(value)
            }
        }else {
            form.clearFields()
        }
    },[valueType])

    const typeOptions = useMemo(() => {
        return [
            ...functionTypeOptions,
            { value: "js", label: "自定义" },
        ];
    },[])


    const isDeep = typeof value === 'object'? value.type : "";

    /**
     * 子事件
     */
    const allChildren = useMemo(() => {
        if(typeof value !== 'object' || !value.type) return null;
        return (
            <Form.List field="all">
                {(fields, { add, remove, move }) => {
                    return (
                        <div className={styles.listitem}>
                            {fields.map(({ key, field }, index) => {
                                return (
                                    <Card size="small"
                                        key={index}
                                        title={`子事件${index + 1}`}
                                        extra={[
                                            <Button key="remove" size="mini"
                                                icon={<IconDelete />}
                                                shape='circle'
                                                style={{
                                                    margin: '0 8px',
                                                }}
                                                onClick={() => remove(index)}
                                            ></Button>,
                                            <Button key="move" size="mini"
                                                shape='circle'
                                                onClick={() => move(index, index > 0 ? index - 1 : index + 1)}
                                            >
                                                {index > 0 ? <IconArrowRise /> : <IconArrowFall />}
                                            </Button>
                                        ]}
                                    >
                                        <Form.Item
                                            label={`行为`}
                                            field={`${field}.type`}
                                        >
                                            <Select
                                                size={size}
                                                placeholder="事件行为"
                                                allowClear
                                                options={typeOptions}
                                            />
                                        </Form.Item>
                                        <Form.Item field={field} noStyle>
                                            {(values, value) => {
                                                return <FormBody field={field} value={values.all[index]}/>
                                            }}
                                        </Form.Item>
                                    </Card>
                                )
                            })}
                            <Button
                                type="primary"
                                style={{ width: "100%" }}
                                onClick={() => {
                                    add({})
                                }}
                            >添加子事件</Button>
                        </div>
                    )
                }}
            </Form.List>
        );
    },[isDeep])

    if(pureFunction){
        return (
            <EditFunction
                isFunction
                value={props.value as string}
                onChange={props.onChange}
            />
        )
    }

    return (
        <Form
            wrapper="div"
            className={styles.form}
            form={form}
            size={size}
            labelCol={{
                style: { maxWidth: 80 }
            }}
            wrapperCol={{
                style: { flex: '1 0 100px', overflow: "hidden" }
            }}
            onValuesChange={(_, values: any) => {
                if(values.type){
                    if(values.type !== "js"){
                        if(props.onChange) props.onChange(values);
                    }else {
                        if(props.onChange) props.onChange(valueType == "string"? value : "() => {}");
                    }
                }else {
                    props.onChange(undefined);
                }
            }}
        >
            <Form.Item
                label="行为"
                field="type"
            >
                <Select
                    size={size}
                    placeholder="事件行为"
                    allowClear
                    options={typeOptions}
                />
            </Form.Item>
            <FormBody value={value} />
            {(value && valueType === "string") && (
                <EditFunction
                    isHljs
                    isFunction
                    value={props.value as string}
                    onChange={props.onChange}
                />
            )}
            {/* {Boolean(allChildren) && <Divider>子事件</Divider>} */}
            {allChildren}
        </Form>
    )
}