import { List } from "@arco-design/web-react";
import PageStore from "../../store";
import { useObserver } from "mobx-react-lite";
import { useMemo } from "react";
import styles from '../index.module.less';
import store from '../store';
import { DragView } from "react-converter-code";

interface HtmlListProps {
    pageStore: PageStore;
}

const HtmlList = ({ pageStore }: HtmlListProps) => {

    return useObserver(() => {
  
      const modules = useMemo(() => {
        return store.htmls;
      },[])
  
        return (
            <List
                className={styles.htmlList}
                grid={{ gutter: [16,24], column: 2 }}
                dataSource={modules}
                render={(item) => {
                    return (
                        <List.Item className={styles.htmlItem} style={{ padding: 0 }}>
                            <DragView data={item}
                                onClick={() => {
                                    pageStore.addList(item as any);
                                }}
                            >
                                <div className={styles.itemName}>
                                    {item.nickname || item.name}
                                </div>
                            </DragView>
                        </List.Item>
                    );
                }}
            />
        )
    
    })
};

export default HtmlList;