import React, { useEffect, useState } from 'react';
import { Modal, Form, Tooltip } from "@arco-design/web-react"
import styles from './index.module.less';
import classNames from 'classnames';
import Store from './store';
import { VarsList, MethodList } from './List';
import { useObserver } from 'mobx-react-lite';
import { getUuid } from '@/utils';
import Context from './context';

interface IndexProps {
    store: Store;
}
const Index = ({ store }: IndexProps) => {

    return useObserver(() => {
        const { visible, closeDialog } = store;
        const [containerId] = useState(() => getUuid());

        // 滚动到指定元素
        function scrollToElement(elementId: string) {
            var container = document.getElementById(containerId);
            var element = document.getElementById(elementId);
          
            // console.log('container', container, element)
            if (container && element) {
              container.scrollLeft = element.offsetLeft;
            }
          }

        useEffect(() => {
            // console.log('store.buildList', store.buildList, store.buildList.length)
            if(store.buildList.length){
                const [item] = store.buildList.slice(-1);
                scrollToElement(item.id);
            }
        },[store.buildList.length])

        // return (
        //     <div style={{ width: '100vh', height: '100vh'}}>132123123</div>
        // )
        return (
            <Modal
                title="表达式构建器"
                className={styles.ExpressionBuilder}
                visible={visible}
                focusLock={false}
                onCancel={() => {
                    if(store.promise){
                        store.promise.reject();
                    }
                    closeDialog();
                }}
                style={{
                    width: '90vw',
                }}
                onOk={() => {
                    return store.onOk();
                }}
            >
                <div id={containerId} className={styles.header}>
                    {store.buildList.map((o, i) => {
                        return (
                            <div id={o.id} className={styles.listItem} key={i}>
                                {Boolean(o.varsList.length) && (
                                    <VarsList
                                        header="存储库数据"
                                        store={store}
                                        $index={i}
                                        dataSource={o.varsList}
                                    />
                                )}
                                {Boolean(o.methodList && o.methodList.length) && (
                                    <MethodList 
                                        header="方法"
                                        store={store}
                                        $index={i}
                                        dataSource={o.methodList}
                                    />
                                )}
                                {/* <List header="方法" /> */}
                            </div>
                        )
                    })}
                </div>
                <div className={classNames('flex items-center', styles.express)}>
                    <div className={styles.title}>表达式</div>
                    <div className={classNames('ellipsis', styles.expressValue)}>
                        {store.expressionText}
                    </div>
                </div>
                <div className={classNames('flex items-center', styles.preview)}>
                    <div className={styles.title}>预览</div>
                    <Tooltip content={store.dataText}>
                        <div className={classNames('flex items-center', 'ellipsis', styles.previewValue)}>
                            {store.dataText}
                        </div>
                    </Tooltip>
                </div>
            </Modal>
        )
    })
}

export default Index;