import { jsonItem } from "@/types/json"
import { getUuid } from "@/utils";
import { Button, Checkbox, Dropdown, Input, InputNumber, InputProps, Menu, Space, Tooltip, Typography, Upload } from "@arco-design/web-react";
import { IconClockCircle, IconClose, IconDelete, IconPlus } from "@arco-design/web-react/icon";
import { HTMLProps, useCallback, useEffect, useMemo, useState } from "react"
import './index.less';
import { ExpressionSelect, NodeInput } from "@/components/custom";

// 是否定义value 类型
export interface JSONListProps<T = jsonItem> extends Omit<HTMLProps<HTMLDivElement>, 'value' | 'onChange' | "size"> {
    value?: T[];
    onChange?: (list: T[]) => void;
    size?: InputProps['size'];
    addText?: string;
    // 分隔符 默认 =
    separator?: string;
    // 可以指定输入的value 允许类型
    supportType?: Array<jsonItem['valueType']>;
    // 是否允许通过构造器选择
    isExpression?: boolean;
    // 是否显示描述
    isDescription?: boolean;
    // 禁止删除
    notDel?: boolean;
    // 禁止添加
    notAdd?: boolean;
    // 禁用复选框
    notCheck?: boolean;
    // 禁止名称编辑
    readOnlyName?: boolean;
}

const FileView = ({ file, onDel }: any) => {
    const { name, size, type } = file;

    return (
        <Tooltip content={JSON.stringify({ name, size, type }, null, '\t')}>
            <Typography.Paragraph ellipsis
                copyable={{
                    text: '删除',
                    tooltips: ['删除', "删除成功"],
                    icon: <IconDelete />,
                    onCopy: onDel
                }}
            >
            {file.name}
            </Typography.Paragraph>
        </Tooltip>
    );
}

const FormItem = ({ item, supportType, update, isExpression, separator, isDescription, del, size, notCheck, readOnlyName }) => {
    const valueType: jsonItem['valueType'] = item.valueType || "Text";
    const typeRender = useMemo(() => {
        if(supportType && supportType.length){
            const dropList = (
                <Menu>
                    {supportType.map((key) => {
                        return (
                            <Menu.Item
                                key={key}
                                onClick={() => {
                                    update({ ...item, valueType: key })
                                }}
                            >{key}</Menu.Item>
                        )
                    })}
                </Menu>
            );
            return (
                <div className="json-list-item-valueType">
                    <Dropdown droplist={dropList} trigger='click' position='br'>
                        [<Button type="text">{valueType}</Button>]
                    </Dropdown>
                </div>
            )
        }
        return null;
    },[supportType, item])
    
    const inputRender = useMemo(() => {
        switch(valueType){
            case 'Text':
                return (
                    <Input size={size}
                        placeholder="value"
                        disabled={!item.enable}
                        className="json-list-item-value"
                        value={item.value}
                        style={{ flex: '2 0 60px'}}
                        onChange={(val) => {
                            update({ ...item, value: val })
                        }}
                        addAfter={isExpression? (
                            <ExpressionSelect
                                onChange={(res) => {
                                    update({ ...item, value: res.value })
                                }}
                            />
                        ) : undefined}
                    />
                )
            break;
            case 'File':
                return (
                    <div className="json-list-item-value">
                        {item.file? (
                            <FileView size={size}
                                file={item.file}
                                onDel={() => {
                                    update({ ...item, file: undefined })
                                }}
                            />
                        ) : (
                            <Upload
                                action='/'
                                limit={1}
                                autoUpload={false}
                                disabled={!item.enable}
                                onChange={(e) => {
                                    update({ ...item, file: e[0].originFile })
                                }}
                                customRequest={(option) => {

                                }}
                            />
                        )}
                    </div>
                )
            break;
            case 'Number':
                return (
                    <InputNumber size={size}
                        placeholder="value"
                        disabled={!item.enable}
                        className="json-list-item-value"
                        value={item.value}
                        style={{ flex: '2 0 60px'}}
                        onChange={(val) => {
                            update({ ...item, value: val.toString() })
                        }}
                    />
                )
            break;
        }
    },[item])
    return (
        <div key={item.key} className="json-list-item">
            {!notCheck && (
                <Checkbox
                    checked={item.enable}
                    onChange={(bool) => {
                        update({ ...item, enable: bool })
                    }}
                />
            )}
            <Input size={size}
                placeholder="name"
                disabled={!item.enable}
                readOnly={readOnlyName}
                className="json-list-item-input"
                value={item.name}
                onChange={(val) => {
                    update({ ...item, name: val })
                }}
                // addAfter={isExpression? (
                //     <ExpressionSelect
                //         onChange={(res) => {
                //             update({ ...item, name: res.value })
                //         }}
                //     />
                // ) : undefined}
            />
            {typeRender}
            <span className="json-list-item-separator">{separator}</span>
            {inputRender}
            {isDescription && (
                <Input size={size}
                    placeholder="描述"
                    disabled={!item.enable}
                    className="json-list-item-description"
                    value={item.description}
                    onChange={(val) => {
                        update({ ...item, description: val })
                    }}
                />
            )}
            {Boolean(del) && (
                <IconClose
                    onClick={() => del(item)}
                    style={{ cursor: 'pointer', fontSize: 16 }}
                />
            )}
        </div>
    )
}

/**
 * 新增JSON List
 */
const JSONList =  ({ 
    value, 
    onChange,
    addText = '新增',
    size,
    separator = '=',
    isExpression = true,
    isDescription,
    supportType,
    notDel,
    notAdd,
    notCheck,
    readOnlyName,
    ...props 
}: JSONListProps) => {

    const list: jsonItem[] = Array.isArray(value)? value : [];
    const onChangeValue = useCallback((list) => {
        if(onChange) onChange(list);
    },[onChange])

    const add = () => {
        if(notAdd) return;
        onChangeValue([...list, { key: getUuid(), enable: true } as jsonItem])
    }

    const del = (item: jsonItem) => {
        if(notDel) return;
        onChangeValue(list.filter((o) => o.key !== item.key))
    }

    const update = (item: jsonItem) => {
        onChangeValue(list.map((o) =>{ 
            if(o.key? o.key === item.key : o.name === item.name) return item;
            return o;
        }))
    }

    return (
        <div {...props} className="custom-json-list">
            {list.map((item, i) => {
                return (
                    <FormItem
                        key={item.key || i}
                        item={item}
                        size={size}
                        supportType={supportType}
                        update={update}
                        isExpression={isExpression}
                        separator={separator}
                        isDescription={isDescription}
                        del={notDel? undefined : del}
                        notCheck={notCheck}
                        readOnlyName={readOnlyName}
                    />
                )
            })}
            {!notAdd && (
                <div>
                    <Button 
                        size={size || "small"}
                        type='secondary'
                        shape='round'
                        icon={<IconPlus />}
                        onClick={add}
                    >
                        {addText}
                    </Button>
                </div>
            )}
        </div>
    )
}

interface JSONEditProps extends JSONListProps {
    value?: any;
    onChange?: (value: any) => any;
}


/**
 * 对象编辑器，会返回对象格式数据
 */
JSONList.JSONEdit = (props) => {
    const [list, setList] = useState([]);

    useEffect(() => {
        // 特殊结构，只在第一次写入信息
        if(props.value && typeof props.value === "object"){
            const result =  Object.keys(props.value).map((k) => {
                return {
                    name: k,
                    value: typeof props.value[k] === "string"? props.value[k] : "",
                    enable: true
                };
            })
            setList(result)
        }
    },[])

    const onChange = (list) => {
        if(!props.onChange) return;
        setList(list);
        if(Array.isArray(list)){
            const obj = {};
            for (const item of list) {
                if(item.name){
                    obj[item.name] = item.value;
                }
            }
            props.onChange(obj);
        }else {
            props.onChange(undefined)
        }
    }

    return <JSONList {...props} value={list} onChange={onChange} />
}

export default JSONList;