import { Button, Empty, Modal, Space, Select, Input, Form, Link, Badge, Switch, Radio, RadioProps, RadioGroupProps, Message } from "@arco-design/web-react";
import { IconSettings, IconDelete, IconPlusCircle, IconPlus, IconCloseCircle, IconFilter } from "@arco-design/web-react/icon";
import { useContext, useEffect, useMemo, useRef, useState } from "react";
import styles from './index.module.less';
import Store from './store'
import { observer, useObserver } from "mobx-react-lite";
import FormRule from './FormRule';
import { computed } from "mobx";
import store from './store';
import PageContext from '@/components/contexts/PageContext';
import { FormBusinessContext } from '@/components/contexts/FormBusinessContext';
import { result } from "lodash";


const RadioGroup = Radio.Group;
const FormItem = Form.Item;
const FormList = Form.List;
interface ControlSettingProps extends RadioGroupProps {
}


function ControlSetting(props: ControlSettingProps) {
    const [visible, setVisible] = useState<boolean>(false);

    const [form] = Form.useForm();
    const page = useContext(PageContext);
    const bus = useContext(FormBusinessContext);
    // console.log('FormBusinessContext', bus);

    const value = useMemo(() => {
        if(typeof props.value === "object" && Array.isArray(props.value)) {
            return "custom";
        }
        return props.value;
    },[props.value])

    useEffect(() => {
        if(visible){
            let originOptions = [];
            if(bus){
                const { fields, itemId, tables } = bus;
                if(itemId){
                    const item = tables.find((o) => o.itemTableName == itemId);
                    originOptions.push({
                        value: `item`,
                        label: "当前表",
                        fields: item? item.itemTableFields.map((o) => ({
                            value: o.value,
                            label: `${o.fieldName}(${o.value})`,
                        })) : [],
                    })
                }
                originOptions.push({
                    value: `forms.${bus.modelKey}.data`,
                    label: itemId? "主表" : "当前表",
                    fields: fields.map((o) => ({
                        value: o.value,
                        label: `${o.fieldComment || o.fieldName}(${o.value})`,
                    }))
                })
            }
            originOptions.push({ value: ``, label: "其他" });
            store.setOriginFields(originOptions);
            if(Array.isArray(props.value)){
                const list = store.valueToList(props.value);
                form.setFieldsValue({ list })
            }
        }
    },[visible,])


    const onChange = (value,e) => {
        if(props.onChange){
            props.onChange(value, e);
        }
    }

    return useObserver(() => {
        return (
            <div>
                {/* <Button 
                    shape="round"
                    type="primary"
                    // icon={<IconSettings />}
                    onClick={() => {
                        setVisible(true)
                    }}
                >
                    <div className={styles.switchBody}>
                        <Switch size="small" style={{ marginRight: 10 }} />
                        条件控制
                    </div>
                </Button> */}
                <RadioGroup
                    type='button'
                    name='lang'
                    value={value}
                    onChange={(value, e) => {
                        if(value === "custom"){
                            setVisible(true);
                        }else{
                            onChange(value, e);
                        }
                    }}
                    defaultValue='Guangzhou'
                >
                    <Radio value={true}>是</Radio>
                    <Radio value={false}>否</Radio>
                    <Radio
                        value='custom'
                        onClick={() => {
                            setVisible(true)
                        }}
                    >
                        <IconFilter />
                    </Radio>
                </RadioGroup>
                <Modal 
                    visible={visible} 
                    title="配置控制条件" 
                    focusLock={false} 
                    className={styles.settingModal}
                    style={{ width: 1050 }} 
                    onCancel={() => {
                        setVisible(false)
                    }}
                    onConfirm={(res) => {
                        const list = form.getFieldValue('list');
                        const result = store.listToValue(list);
                        if(result.length){
                            console.log('result', result)
                            onChange(result, {} as any)
                            setVisible(false)
                        }else {
                            Message.warning("请配置控制条件")
                        }
                    }}
                >
                    <div className={styles.controlSettingContainer}>
                        <div className={`${styles.conditionGroup}`}>
                            <Form form={form}
                                autoComplete="off"
                            >
                                <FormList field="list">
                                    {(fields, { add, remove, move }) => {
                                        return (
                                            <div style={{ paddingLeft: fields.length > 1 ? 60 : 0 }}>
                                                {
                                                    fields?.length ? (
                                                        fields.map((item, index) => {
                                                            return (
                                                                <div key={item.key}>
                                                                    <Badge
                                                                        count={
                                                                            <IconCloseCircle onClick={() => {
                                                                                remove(index)
                                                                            }} className={styles.cursor} />
                                                                        }
                                                                        dotStyle={{
                                                                            height: 20,
                                                                            width: 20,
                                                                            fontSize: 18,
                                                                        }}
                                                                    >
                                                                        <div className={`${styles.condition}`}>
                                                                            <FormRule field={item.field} />
                                                                            {
                                                                                index !== 0 && (
                                                                                    <span className={styles.andOperator}>OR</span>
                                                                                )
                                                                            }
                                                                        </div>
                                                                    </Badge>
                                                                </div>
                                                            );
                                                        })
                                                    ) : (
                                                        <Empty />
                                                    )
                                                }
                                                <FormItem>
                                                    <Button onClick={() => {
                                                        add([{}])
                                                    }} type='primary' icon={<IconPlus />}>添加条件</Button>
                                                </FormItem>
                                            </div>
                                        );
                                    }}
                                </FormList>
                            </Form>
                        </div>
                    </div >
                </Modal >
            </div >
        )
    })

}

export default observer(ControlSetting);

