import ajax from '@/utils/ajax';
import { htmlModuleList } from '@/utils/database';
import config from "@/environments/hoc";
import { Message, Modal } from '@arco-design/web-react';
import { observable, action, toJS, makeObservable } from 'mobx';
import module from "@/store/module";
import { basicsModuleList, moduleStore } from 'react-converter-code';
import { ModuleListProps } from './interface';
import { PublicModule } from '@/types/public';
class Store {

    props: ModuleListProps = {} as any;

    // 当前组件库信息
    @observable activeTab = "1";
    @action
    setActiveTab = (key) => {
      this.activeTab = key;
    }

    // 搜索名称
    name = "";
    // 搜索条件
    @observable input = "";
    @action
    setInput = (val) => {
      this.input = val;
    }
    
    // 选中的标签
    @observable labelKeys = {};
    @action
    changeLabelKeys = (key: string) => {
      if(this.labelKeys[key]){
        delete this.labelKeys[key];
      }else {
        this.labelKeys[key] = true;
      }
      this.labelKeys = { ...this.labelKeys }
    }

    // 其他标签库列表
    @observable tabs = [];
    @action
    setTabs = (list) => {
      this.tabs = list;
    }
    @action
    addTabs = (o: any) => {
      if(!this.tabs.some((o) => o.id == o.id)){
        // 存在的组件不在继续添加了
        this.tabs = [ ...this.tabs, { id: o.id, name: o.name }]
      }
      this.setActiveTab(o.id);
    }

    // 组件库列表
    @observable librarys = [];
    @action
    setLibrarys = (list) => {
        this.librarys = list;
    }
    
    state = {
      mModules: { },
      contexts: { },
    }
    map = new Map();

    constructor(){
      makeObservable(this);
      const { state } = config
      this.state = {
        mModules: { ...state.mModules },
        contexts: { ...state.contexts },
      }
      this.map = new Map([...basicsModuleList,...htmlModuleList].map((o) => [o.key, true]));
    }
    

    // 标签列表
    @observable labels = [];
    @action
    setLabels = (list) => {
        this.labels = list;
    }

    // 组件列表
    @observable modules: PublicModule[] = [];
    @action
    setModules = (list) => {
      this.modules = list;
    }

    // 分页总数
    @observable pagin = {
      total: 0,
      page: 1,
    }

    @action
    setPagin = (obj) => {
      this.pagin = obj;
    }

    m = (uid) => {
      return this.state.mModules[uid] || (() => uid);
    }

    setRender = (o: any) => {
      if(o.jsxRender){
        const fun = new Function('global', o.jsxRender);
        // 直接渲染公共组件，用于加载预览
        this.state.mModules[o.moduleId] = fun({
          ...config,
          // 将state 替换为公共组件属性进行渲染
          state: this.state,
          m: this.m,
        })
      }
    }

    /**
     * 加载依赖组件
     */
    getNodeModules = async (keys: string[]) => {
      return ajax.post('/apijson/get', {
        "PublicModule[]": {
          "count": 0,
          "PublicModule": {
            "moduleId{}": keys,
            "@column":"id,appId,moduleId,name,nickname,description,updatedAt,userId,jsxRender,extraInfo",
          }
        }
      }).then((res) => {
        res.PublicModule.forEach((o) => {
          this.setRender(o);
        })
      })
    }

    /**
     * 获取所有组件
     */
    initModules = () => {
      let join = "</Component";
      let params = {};
      let moduleParams = {};
      const keys = Object.keys(this.labelKeys);
      if(keys.length){
        join = "</Component,</PublicTagModule";
        params = {
          "PublicTagModule":{
            "mId@":"/PublicModule/id",
            "tagId{}":keys,
            "@group":"mId",
            "@column":"mId,tagId"
          },
        }
      }
      if(this.name){
        moduleParams[`nickname$`] = `%${this.name}%`
      }
      ajax.post('/apijson/get', {
        "PublicModule[]":{
          "query":2,
          "page": this.pagin.page,
          "count":10,
          "PublicModule":{
            "@column":"id,appId,moduleId,name,nickname,description,updatedAt,userId,jsxRender,extraInfo",
            ...moduleParams,
            "@order":"updatedAt-"
          },
          "Component":{
            "id@":"/PublicModule/componentId",
            "@column":"name:componentName"
          },
          "PublicTagModule[]":{
            "join":"</TagModule",
            "PublicTagModule":{
              "mId@":"PublicModule[]/PublicModule/id",
              "@column":"mId,tagId,id:PublicTagModuleID"
            },
            "TagModule":{
              "id@":"/PublicTagModule/tagId",
              "@column":"id,name"
            }
          },
          ...params,
          "join": join,
        },
        "info@":"/PublicModule[]/info"
      }).then(async (res) => {
        let components = [];
        const list = res.PublicModule.map((o) => {
          if(o.extraInfo) {
            o.extraInfo = JSON.parse(o.extraInfo);
            if(o.extraInfo.components){
              components = components.concat(o.extraInfo.components);
            }
          };
          this.setRender(o);
          return o;
        })
        // 加载模块对应的子模块（改为异步加载）
        // const keys = Array.from(new Set(components)).filter((k) => {
        //   return !(this.state.mModules[k] || this.state.contexts[k] || this.map.has(k));
        // });
        // if(keys.length){
        //   await this.getNodeModules(keys);
        // }
        this.setModules(list);
        this.setPagin({ ...this.pagin, total: res.info.total });
      })
    }


    /**
     * 获取组件库对应组件列表
     */
    getLibraryModules = (uid: string) => {
      return ajax.post('/apijson/get', {
        "PublicModule[]":{
          "count":0,
          "PublicModule":{
            "@column":"id,appId,moduleId,name,nickname,description,updatedAt,userId,jsxRender,extraInfo",
            "componentId": uid,
            "@order":"updatedAt-"
          },
          "PublicTagModule[]":{
            "join":"</TagModule",
            "PublicTagModule":{
              "mId@":"PublicModule[]/PublicModule/id",
              "@column":"mId,tagId,id:PublicTagModuleID"
            },
            "TagModule":{
              "id@":"/PublicTagModule/tagId",
              "@column":"id,name"
            }
          },
        },
      }).then(async (res) => {
        let components = [];
        const list = res.PublicModule.map((o) => {
          if(o.extraInfo) {
            o.extraInfo = JSON.parse(o.extraInfo);
            if(o.extraInfo.components){
              components = components.concat(o.extraInfo.components);
            }
          };
          this.setRender(o);
          return o;
        })
        const keys = Array.from(new Set(components)).filter((k) => {
          return !(this.state.mModules[k] || this.state.contexts[k] || this.map.has(k));
        });
        if(keys.length){
          await this.getNodeModules(keys);
        }
        return list;
      })
    }

    /**
     * 获取组件库列表
     */
    initLibrary = () => {
        ajax.post('/apijson/get', {
            "Component[]":{
                "page":1,
                "count": 0,
                "Component":{
                    "@column":"id,name,description,createdAt,updatedAt",
                    "@order":"-createdAt"
                }
            },
        }).then((res) => {
            this.setLibrarys(res.Component);
        })
    }

    /**
     * 获取所有组件
     */
    initLables = () => {
        ajax.post('/apijson/get', {
            "TagModule[]":{
                "page":1,
                "count":0,
                "TagModule":{
                    "@column":"id,name,updatedAt",
                    "@order":"-updatedAt"
                }
            }
        }).then((res) => {
            this.setLabels(res.TagModule);
        })
    }


    /**
     * 已经确认要同步
     * @param cList 要新增的组件
     * @param uList 要更新的组件
     */
    syncModuleOk = ({ cList, uList }) => {

      let params = {};
      if(cList.length){
        // 添加需要新增的组件
        params['post'] = {
          "Module[]": cList.map(({ id, ...o }) => {
            return {
              ...o,
              name: module.getModuleName(o.name),
            }
          })
        }
      }
      if(uList.length){
        // 添加需要更新的组件
        params['put'] = {
          "Module[]": uList.map((o) => {
            return {
              ...o,
              id: module.keyMap.get(o.moduleId)
            }
          })
        }
      }
      console.log('params', params);
      ajax.post('/apijson/transaction', params).then(() => {
        Message.success("下载成功");
        const { onAdd, onChange } = this.props;
        if(cList.length){
          if(onAdd) onAdd(cList);
        }
        if(uList.length){
          if(onChange) onChange(uList);
        }
      });
    }


    /**
     * 同步组件列表
     */
    syncModule = async (list: any[]) => {
      let components = [];
      list.forEach((o) => {
        components.push(o.moduleId);
        if(o.extraInfo){
          if(o.extraInfo.components){
            components = components.concat(toJS(o.extraInfo.components));
          }
        }
      })
      const keys = Array.from(new Set(components));
      // 获取所有组件列表
      const lists = await ajax.post('/apijson/get', {
        "PublicModule[]":{
          "count":0,
          "PublicModule":{
            "@column":"id,appId,moduleId,name,nickname,imgUrl,description,category,display,platform,price,manufacturer,props,source,content,jsxRender,extraInfo",
            "moduleId{}": keys,
            "@order":"updatedAt-"
          },
        }
      }).then((res) => res.PublicModule.map((o) => {
        return {
          ...o,
          props: JSON.parse(o.props || '{}'),
          extraInfo: JSON.parse(o.extraInfo || '{}'),
        }
      }));
      
      // 检测需要新增的组件
      let createList = lists.filter((o) => !module.keyMap.has(o.moduleId));
      // 检测需要更新的组件
      let updateList = lists.filter((o) => module.keyMap.has(o.moduleId));

      console.log('lists', lists, createList, updateList)
      let content = "";
      if(createList.length && updateList.length){
        content = `当前共需要下载（${
          createList.map((o) => o.nickname || o.name).join('、')
        }）组件，同时以下（${
          updateList.map((o) => o.nickname || o.name).join('、')
        }）组件已经存在将会被一起更新，请注意当前更新影响组件较多，同步后将会影响本地组件已修改的内容`
      }else if(createList.length){
        content = `请确认下载（${
          createList.map((o) => o.nickname || o.name).join('、')
        }）组件`
      }else if(updateList.length){
        content = `当前无新增组件，以下（${
          updateList.map((o) => o.nickname || o.name).join('、')
        }）组件需要进行更新，请注意更新会将本地已修改组件内容覆盖，`
      }
      Modal.confirm({
        title: "下载提示",
        content,
        onOk: () => {
          this.syncModuleOk({
            cList: createList,
            uList: updateList
          });
        }
      })

    }

}

export default Store;