import { Card, Collapse, Input, List, Tooltip } from "@arco-design/web-react";
import PageStore from "../../store";
import { useObserver } from "mobx-react-lite";
import { useMemo } from "react";
import styles from '../index.module.less';
import store from '../store';
import { DragView } from "react-converter-code";

interface BuiltInProps {
    pageStore: PageStore;
}
const BuiltIn = ({ pageStore }: BuiltInProps) => {

    return useObserver(() => {
  
      const modules = useMemo(() => {
        return store.components;
      },[store.components])
  
      return (
        <Collapse bordered={false} defaultActiveKey={modules.map((o) => o.key)}>
          {modules.map((o) => {
            return (
              <Collapse.Item key={o.key} name={o.key} header={o.name}>
                <List
                  className={styles.list}
                  grid={{ gutter: [8, 16], column: 2 }}
                  dataSource={o.modules}
                  render={(item) => {
                    return (
                      <Tooltip content={item.nickname || item.name}>
                      <List.Item className={styles.listItem} style={{ padding: 0 }}>
                        <DragView data={item}
                          onClick={() => {
                            pageStore.addList(item as any);
                          }}
                        >
                          {item.imgUrl && (
                            <div className={styles.item}>
                              <img
                                className={styles.image}
                                alt="dessert"
                                src={item.imgUrl || require('@/assets/module/component.png')}
                              />
                            </div>
                          )}
                          <div className={styles.itemName}>
                            {item.nickname || item.name}
                          </div>
                        </DragView>
                      </List.Item>
                      </Tooltip>
                    );
                  }}
                />
              </Collapse.Item>
            )
          })}
        </Collapse>
      )
  
    })
};

export default BuiltIn