import React, { useContext, useEffect, useMemo } from "react";
import { Divider, Form, Input, Select, Radio, Checkbox, InputNumber } from "@arco-design/web-react";
import { dialogTypeOptions, functionConfig, functionHistoryTypes, functionHrefTargetOptions, functionMessageTypeOptions, functionTypes, historyTypeOptions, methodOptions } from "@/types/function";
import styles from "../index.module.less";
import _ from 'lodash';
import Store from './store';
import { CustomPageContext } from "@/components/CustomPage/context";
import { JSONList, Selector, Translation, TreeSelector } from "@/components/custom";

interface EditFunctionConfigProps {
    field?: string;
    value?: functionConfig | string;
}
export default (props: EditFunctionConfigProps) => {
    const { value, field } = props;
    const size = "small";
    const isDeep = typeof value === 'object'? value.type : "";
    const page = useContext(CustomPageContext);
    const store =useMemo(() => {
        return new Store(page);
    },[page])


    console.log('pageContext', page);

    const getField = (key) => field? `${field}.${key}` : key;


    const formChildren = useMemo(() => {
        if(typeof value === "object"){
            switch(value.type){
                case functionTypes.history:
                    return (
                        <React.Fragment>
                            <Form.Item label="操作方法" field={getField('history.type')}>
                                <Select allowClear placeholder="请选择" options={historyTypeOptions} />
                            </Form.Item>
                            <Form.Item noStyle>
                                {(values) => {
                                    const type = _.get(values, getField('history.type'));
                                    return (
                                        <React.Fragment>
                                            { type === functionHistoryTypes.go && (
                                                <Form.Item label="回退位置" field={getField('history.count')}>
                                                    <InputNumber placeholder="回退页数" />
                                                </Form.Item>
                                            )}
                                            {(type === functionHistoryTypes.push || type === functionHistoryTypes.replace) && (
                                                <React.Fragment>
                                                    <Form.Item label="目标页面" field={getField('history.path')}>
                                                        <Input placeholder="页面地址" />
                                                    </Form.Item>
                                                    <Form.Item
                                                        label="路由参数"
                                                        tooltip="所有启用的参数会按照key=value的方式拼接在url后面"
                                                        layout="vertical"
                                                        field={getField('history.params')}
                                                    >
                                                        <JSONList isExpression/>
                                                    </Form.Item>
                                                </React.Fragment>
                                            )}
                                        </React.Fragment>
                                    )
                                }}
                            </Form.Item>
                        </React.Fragment>
                    )
                case functionTypes.href:
                    return (
                        <React.Fragment>
                            <Form.Item label="跳转链接" field={getField('href.url')}>
                                <Input placeholder="超链接地址" />
                            </Form.Item>
                            {/* <Divider>参数</Divider> */}
                            <Form.Item label="跳转方式" field={getField("href.target")}>
                                <Select allowClear placeholder="请选择" options={functionHrefTargetOptions} />
                            </Form.Item>
                            <Form.Item
                                label="地址参数"
                                tooltip="所有启用的参数会按照key=value的方式拼接在url后面"
                                layout="vertical"
                                field={getField('href.params')}
                            >
                                <JSONList isExpression/>
                            </Form.Item>
                        </React.Fragment>
                    )
                case functionTypes.message:
                    return (
                        <React.Fragment>
                            <Form.Item label="提示文本" field={getField("message.text")}>
                                <Translation />
                            </Form.Item>
                            <Form.Item label="提示方式" field={getField("message.type")}>
                                <Select allowClear placeholder="请选择" options={functionMessageTypeOptions} />
                            </Form.Item>
                        </React.Fragment>
                    )
                case functionTypes.form:
                    return (
                        <React.Fragment>
                            <Form.Item label="选择表单" field={getField('form.key')}>
                                <Select size={size}
                                    allowClear
                                    options={store.formOptions}
                                    placeholder="请选择"
                                />
                            </Form.Item>
                            <Form.Item label="表单事件" field={getField('form.eventType')}>
                                <Radio.Group type="button" size={size}>
                                    <Radio value="submit">提交</Radio>
                                    {/* <Radio value="reset">重置</Radio> */}
                                    <Radio value="validate">验证</Radio>
                                </Radio.Group>
                            </Form.Item>
                        </React.Fragment>
                    )
                case functionTypes.form:
                    return (
                        <React.Fragment>
                            <Form.Item label="选择表单" field={getField('table.key')}>
                                <Select size={size}
                                    allowClear
                                    options={store.tableOptions}
                                    placeholder="请选择"
                                />
                            </Form.Item>
                            <Form.Item label="表单事件" field={getField('table.eventType')}>
                                <Radio.Group type="button" size={size}>
                                    {/* <Radio value="submit">提交</Radio> */}
                                    {/* <Radio value="reset">重置</Radio> */}
                                    <Radio value="validate">验证</Radio>
                                </Radio.Group>
                            </Form.Item>
                        </React.Fragment>
                    )
                case functionTypes.busItem:
                    return (
                        <React.Fragment>
                            <Form.Item label="选择表单" field={getField('busItem.key')}>
                                <Select size={size}
                                    allowClear
                                    options={store.formOptions}
                                    placeholder="请选择"
                                />
                            </Form.Item>
                            <Form.Item noStyle shouldUpdate>
                                {(values) => {
                                    const key = _.get(values, getField('busItem.key'));
                                    let options = [];
                                    if(key && store.busOptionNode[key]){
                                        options = store.busOptionNode[key];
                                    }
                                    return (
                                        <Form.Item label="业务子表" field={getField('busItem.tableKey')}>
                                            <Select size={size} 
                                                allowClear
                                                options={options}
                                            />
                                        </Form.Item>
                                    )
                                }}
                            </Form.Item>
                            <Form.Item label="表单事件" field={getField('busItem.eventType')}>
                                <Radio.Group type="button" size={size}>
                                    <Radio value="add">添加</Radio>
                                </Radio.Group>
                            </Form.Item>
                        </React.Fragment>
                    )
                case functionTypes.api:
                    return (
                        <React.Fragment>
                            <Form.Item label="请求地址" field={getField('api.url')}>
                                <Input placeholder="url" />
                            </Form.Item>
                            <Form.Item label="请求方式" field={getField('api.method')}>
                                <Select placeholder="请选择" options={methodOptions} />
                            </Form.Item>
                            <Form.Item label="请求参数" layout="vertical" field={getField('api.body')}>
                                <JSONList isExpression />
                            </Form.Item>
                            <Form.Item label="成功提示" field={getField('api.successText')}>
                                <Translation />
                            </Form.Item>
                        </React.Fragment>
                    )
                case functionTypes.dialog:
                    return (
                        <React.Fragment>
                            <Form.Item label="选择弹窗" field={getField('dialog.key')}>
                                <Select placeholder="请选择" allowClear options={store.dialogOptions} />
                            </Form.Item>
                            <Form.Item label="操作事件" field={getField('dialog.type')}>
                                <Select placeholder="选择事件" allowClear options={dialogTypeOptions} />
                            </Form.Item>
                        </React.Fragment>
                    )
                case functionTypes.task:
                    return (
                        <React.Fragment>
                            <Form.Item label="任务组" field={getField('task.groupId')}>
                                <TreeSelector type="customTaskFlowGroup" />
                            </Form.Item>
                            <Form.Item noStyle shouldUpdate>
                                {(values) => {
                                    const groupId = _.get(values, getField('task.groupId'))
                                    return (
                                        <Form.Item label="任务名称" field={getField('task.customTaskFlow')}>
                                            <Selector
                                                type="customTaskFlow"
                                                params={{ groupId }}
                                            />
                                        </Form.Item>
                                    )
                                }}
                            </Form.Item>
                        </React.Fragment>
                    )
            }
        }
        return null;
    },[isDeep])


    return formChildren
}