export default `
import React, { ReactNode } from 'react';

export interface ForProps {
    /**
     * 数据名称列表
     * @default item
     */
    each: string;
    /**
     * 列表数据源
     */
    of: any[];
    /**
     * 列表序列号
     * @default index
     */
    index?: string;
    children: ReactNode;
}
export const For = (props: ForProps) => {
    if(!Array.isArray(props.of)) return null;

    return props.of.map((o) => props.children);
}
`