import React, { useState, useEffect } from 'react';
import { Button, Input, InputProps, Modal } from '@arco-design/web-react';
import { IconCodeBlock } from '@arco-design/web-react/icon';

export interface EditClassProps extends InputProps {
    title?: string;
    
}
export default ({ title, ...props }: EditClassProps) => {


    const [visible, setVisible] = useState<boolean>(false);
    const [value, setValue] = useState(props.value);

    useEffect(() => {
        setValue(props.value);
    },[props.value])

    return <Input {...props} placeholder="推荐使用tailwindcss" />

    return (
        <div>
            <Button shape='round' type='primary' icon={<IconCodeBlock />}
                onClick={() => {
                    setVisible(true)
                }}
            >
                编辑
            </Button>
            <Modal visible={visible}
                title={title || "Style"}
                focusLock={false}
                style={{ width: 800 }}
                onCancel={() => {
                    setVisible(false)
                }}
                onConfirm={(e) => {
                    if(props.onChange){
                        props.onChange(value, e)
                        setVisible(false);
                    }else {
                        setVisible(false);
                    }
                }}
            >
                <Input {...props} />
            </Modal>
        </div>
    )
}
