import JSZip from 'jszip';

/**
 * 下载zip文件
 */
export function dwonloadZip(zip: JSZip, name: string){
    zip.generateAsync({ type: "blob", compression: "DEFLATE", compressionOptions: { level: 9 } })
    .then(function (content) {
        // 创建下载链接
        var blob = new Blob([content]);
        var url = window.URL.createObjectURL(blob);

        // 创建下载按钮
        var a = document.createElement("a");
        a.href = url;
        a.download = `${name}.zip`;
        document.body.appendChild(a);

        // 触发点击以下载
        a.click();

        // 清理
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
    });

}


interface fileItem {
    url: string;
    text: string | ArrayBuffer;
}
// 创建zip 文件并下载
export function createZip(list: fileItem[] = [], fileName?: string){
    var zip = new JSZip();

    // 添加文件到ZIP
    // zip.file("file.txt", "Hello, world!");
    // zip.file("image.jpg", binaryData, { binary: true }); // 添加二进制文件
    for (const item of list) {
        zip.file(item.url, item.text);
    }

    dwonloadZip(
        zip,
        fileName || Date.now().toString()
    );
}


/**
 * 创建zip 文件
 */
export function createZipFile(list: fileItem[] = []){
    var zip = new JSZip();
    for (const item of list) {
        zip.file(item.url, item.text);
    }
    return zip.generateAsync({ type: "blob", compression: "DEFLATE", compressionOptions: { level: 9 } });
}


/**
 * 解压zip 文件信息
 */
export async function parseZipFile(zipUrl: string){
    // 使用JSZip解压ZIP文件
    var zip = new JSZip();

    const file: any = await fetch(zipUrl);
    const buffer = await file.arrayBuffer();
    // 从File对象或URL加载ZIP文件
    const result = [];
    await zip.loadAsync(buffer)
    .then(function (zip) {
        // 列出ZIP中的文件
        zip.forEach(async function (relativePath, file) {
            const ext = relativePath.split('.').pop();
            if (['html', 'text', 'txt', 'js', 'css', 'ts', 'vue'].includes(ext)) {
                // 处理文本内容
                result.push(file.async("text").then(function (content) {
                    return {
                        url: relativePath,
                        text: content,
                    } as fileItem
                }));
            } else {
                // 处理二进制内容
                result.push(file.async("arraybuffer").then(function (content) {
                    return {
                        url: relativePath,
                        text: content,
                    } as fileItem
                }));
            }
            
        });
    });
    return Promise.all(result);
}