import React, { useMemo } from "react";
import { Button, Empty, Modal, Space, Select, Input, Form, Link, Badge, Switch, InputNumber } from "@arco-design/web-react";
import styles from '../index.module.less';
import _ from 'lodash';
import store from '../store';
import { controlConfig } from "@/types/verify";

const Option = Select.Option;
const FormItem = Form.Item;
const FormList = Form.List;
interface FormValueProps {
    field: string;
    values: controlConfig[][];
}
export default ({ values, field }: FormValueProps) => {
    const getField = (key) => field? `${field}.${key}` : key;
    const operator: controlConfig['operator'] = _.get(values, getField('operator')) as any;
    const valueType: controlConfig['valueType'] = _.get(values, getField('valueType')) as any;

    
    const bodyChildren = useMemo(() => {
        switch(operator){
            case "regexp":
                return (
                    <Form.Item className={styles.mSmall} field={getField('')}>
                        <Select allowClear
                            placeholder="正则选择"
                            options={[]}
                        />
                    </Form.Item>
                )
            default:
                const getValueNode = (valueType) => {
                    switch(valueType){
                        case "number":
                            return (
                                <FormItem className={styles.mSmall} field={getField('value')}>
                                    <InputNumber style={{ width: 154 }} placeholder='请输入判断值' />
                                </FormItem>
                            )
                        case "boolean":
                            return (
                                <FormItem className={styles.mSmall} field={getField('value')} triggerPropName="checked">
                                    <Switch />
                                </FormItem>
                            )
                        default:
                            return (
                                <FormItem className={styles.mSmall} field={getField('value')}>
                                    <Input style={{ width: 154 }} allowClear placeholder='请输入判断值' />
                                </FormItem>
                            )
                            
                    }
                }
                return (
                    <Space>
                        <FormItem className={styles.mSmall} field={getField('valueType')}>
                            <Select
                                placeholder='请选择数据类型'
                                style={{ width: 154 }}
                            >
                                {store.dataTypeOptions.map((option, index) => (
                                    <Option key={index} value={option.value}>
                                        {option.label}
                                    </Option>
                                ))}
                            </Select>
                        </FormItem>
                        {getValueNode(valueType)}
                    </Space>   
                )
        }
    },[operator, valueType])

    return (
        <div style={{ width: 320 }}>
            {bodyChildren}
        </div>
    )
}