import React, { useEffect, useState, useMemo, forwardRef, useImperativeHandle } from 'react';
import * as monaco from 'monaco-editor';
import '../style.less';
import Store from './store'
import classnames from 'classnames';
import '../init';
import { MonacoJsProps } from './interface';
import { ExpressionSelect } from '@/components/custom';
import { Button } from '@arco-design/web-react';
import { IconPen } from '@arco-design/web-react/icon';

const MonacoEditor = ({
  value = ``,
  readOnly,
  disabled,
  selectionVariable,
  onChange,
  ...props
}: MonacoJsProps, ref) => {
  const [id] = useState(() => `monaco-${Math.random().toString(32).slice(2)}`);
  const [store] = useState(() => new Store());


  useImperativeHandle(ref, () => {
    return {
      insertText: store.insertText.bind(store),
    }
  },[])

  useEffect(() => {
    if (
      store.monacoInstance &&
      value == store.value
    ) {
      return;
    }
    const monacoValue = value;
    if (!store.monacoInstance) {
      // 逻辑线替换为TS 逻辑
      store.model = monaco.editor.createModel(
        monacoValue,
        'typescript',
        // 'javascript',
        monaco.Uri.parse(`${id}.tsx`)
      );
      store.monacoInstance = monaco.editor.create(
        document.getElementById(id) as HTMLElement,
        {
          model: store.model,
          readOnly: readOnly || disabled,
        }
      );
      store.monacoInstance.onMouseDown((event) => {
        if (event.event.leftButton) {
          // 记录光标的位置信息
          store.position = store.monacoInstance.getPosition(event.event);
        }
      })
      store.monacoInstance.onDidChangeModelContent(() => {
        const value = store.monacoInstance.getValue();
        // console.log('monacoInstance', value)
        try {
          // const data = sanitizeInput(value); // 过滤非法字符 
          store.setValue(value);
          if (onChange) {
            onChange(value);
          }
        } catch {}
      });
    } else {
      store.monacoInstance.setValue(monacoValue);
    }
  }, [value]);

  useEffect(() => {
    if(store.monacoInstance){
        // editable 是否启用编译器， true = 启用 
        store.monacoInstance.updateOptions({ editable: !disabled });
    }
  },[disabled])

  useEffect(() => {
    return () => {
      if (store.monacoInstance) {
        store.monacoInstance.dispose(); //使用完成销毁实例
        store.model.dispose(); // 销毁model实例
      }
    };
  }, []);

  return (
    <div style={{ position: 'relative' }}>
      {selectionVariable && (
        <ExpressionSelect
          onChange={({ value }) => {
            store.insertText(value);
          }}
        >
          <Button size="small" className="mocaco-selection-variable" shape='circle' type='primary' icon={<IconPen />} />
        </ExpressionSelect>
      )}
      <div
        className={classnames({
          'mocaco-editor-dev': true,
        })}
        {...props}
        id={id}
      ></div>
    </div>
  );
};

export default forwardRef(MonacoEditor);
