import React, { useMemo, useState } from "react";
import { Input, type InputProps, Modal, Button } from "@arco-design/web-react";
import { IconCodeBlock } from "@arco-design/web-react/icon";
import { isJsxString, isTranslation } from "@/utils/is";
import { MonacoJSEditor } from "@/components/MonacoEditor";
import classNames from 'classnames';
import { jsTojsString, jsStringToJs } from "@/utils/js";
import styles from './index.module.less';
import { jsVarToRuleVar } from "src/utils/js";


interface props extends InputProps {

}

const EditInputJS = (props) => {
    
    const [visible, setVisible] = useState(false);
    const [val, setVal] = useState<string>('');

    const isJS = useMemo(() => {
        return isJsxString(props.value)
    },[props.value])

    const isString = useMemo(() => {
        if(isJS) return false;
        return typeof props.value === 'string';
    },[props.value])

    const value = useMemo(() => {
        if(isJS) return jsStringToJs(props.value)
        return props.value;
    },[props.value])


    return (
        <React.Fragment>
            <Input
                addAfter={
                    <Button
                        type={isString? undefined: 'primary'}
                        onClick={() => {
                            setVal(value? (isJS? value : JSON.stringify(value)) : undefined);
                            setVisible(true)
                        }}
                        icon={(
                            <IconCodeBlock
                                className="cursor-pointer"
                            />
                        )}
                    />
                }
                readOnly={!isString}
                placeholder="请输入"
                {...props}
                className={classNames(styles.input, props.className)}
                value={value}
            />
            {visible && (
                <Modal
                    visible={visible}
                    title="JS变量"
                    onCancel={() => {
                        setVisible(false);
                    }}
                    onOk={() => {
                        props.onChange(jsVarToRuleVar(val));
                        setVisible(false)
                    }}
                >
                    <MonacoJSEditor
                        {...props}
                        selectionVariable
                        value={val}
                        onChange={(val) => {
                            setVal(val);
                        }}
                    />
                </Modal>
            )}
        </React.Fragment>
    )
}


export default EditInputJS;