import React, { useState } from 'react';
import { Button, Empty, Modal, Space, Select, Input, Form, Link, Badge } from "@arco-design/web-react";
import { IconSettings, IconDelete, IconPlusCircle, IconPlus, IconCloseCircle } from "@arco-design/web-react/icon";
import styles from '../index.module.less';
import FormBody from '../FormBody';

const Option = Select.Option;
const FormItem = Form.Item;
const FormList = Form.List;
interface FormBodyProps {
    field: string;
}
export default ({ field }: FormBodyProps) => {

    return (
        <FormList field={field}>
            {(cFields, { add, remove, move }) => {
                return (
                    <div style={{ paddingLeft: 50 }}>
                        {
                            cFields.map((cItem, cIndex) => {
                                return (
                                    <div className={styles.childrenConditionGroup} key={cIndex}>
                                        <FormBody
                                            field={cItem.field}
                                            parentField={field}
                                            remove={() => {
                                                remove(cIndex);
                                            }} 
                                        />
                                        {
                                            cIndex !== 0 && <span className={styles.childrenAndOperator}>AND</span>
                                        }
                                    </div>

                                )
                            })
                        }
                        <Link onClick={() => {
                            add({ })
                        }} icon={<IconPlusCircle />}>
                            添加条件
                        </Link>
                    </div>
                )
            }}
        </FormList>
    )
}